"""Rules-in-context ablation for zero-shot LLM baseline.Default path uses unified prompts from ``zo_train.prompts`` (JSON + numbered input, no digest).Set ``ZO_RULES_IN_CONTEXT=1`` to append grammar/vocab/forbidden-rule digests for comparison runs.Snapshots: ``prompt_snapshots/zeroshot_rules_v5.md`` … ``zeroshot_rules_v9.md``."""from __future__ import annotationsimport osimport refrom functools import lru_cachefrom pathlib import Pathfrom zo_train.datagen import ALL_RULESfrom zo_train.fab import all_steps, default_data_dirfrom zo_train.prompts import build_messages as _build_unified_messagesfrom zo_train.prompts import load_system_generalfrom zo_eval.submission import AnomalyInput, ValidInput# --- Rules digest sections (ablation only) -----------------------------------_GRAMMAR_NOTE = """\Grammar note: labels like PREFIX, PASSIVATION_BLOCK, TEST_SUITE, and SUFFIX name phases in the rulesdoc — they are not fab steps. Predictions must use concrete step names from the allowed list."""_PREDICTION_MISTAKES = """\Common mistakes to avoid:- Skipping ahead to a later process phase instead of the very next step.- Using grammar phase labels (…_BLOCK, TEST_SUITE, SUFFIX, PREFIX) as step predictions.- Using RULE_* identifiers as steps — those label anomaly violations, not fab steps.- Misspelling step names — copy exactly from the allowed list."""_ANOMALY_GUIDANCE = """\Anomaly decision rules:1. RULE_* IDs name violation patterns — a sequence is valid when that pattern does not apply.2. Check the sequence against every forbidden rule listed below — consider each one carefully.3. If any listed forbidden rule applies, set valid=false and "rule" to that rule ID.4. Set valid=true only when none of the listed forbidden rules apply.5. When valid=false, set "rule" to exactly one forbidden rule ID (not a step name).6. Reason first in "reasoning", then set valid and rule to match."""_FAMILY_PREP = {    "MOSFET": (        "MOSFET family prep: SUBSTRATE CHECK → EPITAXY PREP → EPITAXIAL DEPOSITION → "        "MEASURE EPITAXY THICKNESS → MEASURE RESISTIVITY → EPITAXY ANNEAL → WAFER SURFACE CLEAN."    ),    "IGBT": (        "IGBT family prep: EPITAXIAL WAFER CHECK → MEASURE EPITAXY THICKNESS → MEASURE RESISTIVITY → "        "[EPITAXIAL REWORK CHECK] → EPITAXIAL LAYER PREP. Uses 6 litho levels in process cycles."    ),    "IC": (        "IC family prep: WAFER CLEAN PRE-GRIND → GRINDING WAFER BACKSIDE → MEASURE GEOMETRY → "        "ETCH WET BACKSIDE → RINSE → DRY WAFER BACKSIDE → BACKSIDE CLEAN → MEASURE BACKSIDE ROUGHNESS. "        "Backside grind happens early; BACKSIDE_BLOCK covers final clean/protection only."    ),}_LITHO_TEMPLATE = """\Lithography block template (every litho cycle):SPIN COAT PHOTORESIST → SOFT BAKE → ALIGN MASK LEVEL N → EXPOSE LITHO LEVEL N →[POST EXPOSE BAKE] → DEVELOP PHOTORESIST → pattern inspection → [HARD BAKE] → etch → STRIP RESIST →CLEAN AFTER ETCH (mandatory after etch before next deposition)."""_BACKBONE = """\Shared process backbone (all families):PREFIX → PRE_PROCESS_CLEAN → FAMILY_SPECIFIC_PREP → FIRST_OXIDATION → PROCESS_CYCLES→ ILD_BLOCK → VIA_BLOCK → METAL_BLOCK → PASSIVATION_BLOCK → BACKSIDE_BLOCK→ FINAL_INSPECTION → TEST_SUITE (includes WAFER SORT TEST before ship) → SUFFIX (LOT RELEASE → SHIP LOT)."""def use_rules_in_context() -> bool:    """True when ``ZO_RULES_IN_CONTEXT=1`` — append full rules digest to system prompt."""    return os.environ.get("ZO_RULES_IN_CONTEXT", "").strip().lower() in ("1", "true", "yes")def generation_rules_path(data_dir: Path | None = None) -> Path:    return (data_dir or default_data_dir()) / "generation_rules.md"def load_generation_rules(data_dir: Path | None = None) -> str:    path = generation_rules_path(data_dir)    return path.read_text(encoding="utf-8")def _extract_between(text: str, start: str, end: str | None) -> str:    pat_start = re.compile(rf"^##\s+{re.escape(start)}\s*$", re.MULTILINE)    m = pat_start.search(text)    if not m:        return ""    start_idx = m.end()    if end:        pat_end = re.compile(rf"^##\s+{re.escape(end)}\s*$", re.MULTILINE)        m_end = pat_end.search(text, start_idx)        chunk = text[start_idx : m_end.start()] if m_end else text[start_idx:]    else:        chunk = text[start_idx:]    return chunk.strip()def _condense_forbidden(section: str) -> str:    lines: list[str] = ["Forbidden patterns (check the sequence against these only):"]    for rule in ALL_RULES:        pat = re.compile(rf"###\s+{re.escape(rule)}\s*\n\*\*(.+?)\*\*", re.DOTALL)        m = pat.search(section)        if m:            desc = re.sub(r"\s+", " ", m.group(1)).strip()            lines.append(f"- {rule}: {desc}")        else:            lines.append(f"- {rule}")    lines.append(f"Allowed rule IDs for valid=false: {', '.join(ALL_RULES)}")    return "\n".join(lines)@lru_cache(maxsize=8)def build_step_vocab_digest(family: str) -> str:    fam = (family or "").strip().upper()    steps = sorted(all_steps(fam))    if not steps:        return ""    body = "\n".join(f"- {s}" for s in steps)    return (        f"Allowed fab step names for {fam} ({len(steps)} steps — predictions must use these exact names):\n"        f"{body}"    )@lru_cache(maxsize=8)def build_grammar_digest(family: str | None = None) -> str:    parts = [        "Process grammar reference:",        _GRAMMAR_NOTE,        "",        _BACKBONE,        "",        _LITHO_TEMPLATE,        "",    ]    fam = (family or "").strip().upper()    if fam in _FAMILY_PREP:        parts.extend([f"Active product family: {fam}", _FAMILY_PREP[fam], ""])    else:        parts.extend(            [                "Family-specific prep blocks:",                _FAMILY_PREP["MOSFET"],                _FAMILY_PREP["IGBT"],                _FAMILY_PREP["IC"],                "",            ]        )    return "\n".join(parts)@lru_cache(maxsize=1)def build_anomaly_rules_digest() -> str:    text = load_generation_rules()    forbidden_raw = _extract_between(text, "3. Forbidden Patterns", "4. Variation Axes")    return _condense_forbidden(forbidden_raw)@lru_cache(maxsize=8)def build_rules_digest(family: str | None = None) -> str:    fam = (family or "MOSFET").upper()    return "\n\n".join(        [build_grammar_digest(fam), build_step_vocab_digest(fam), build_anomaly_rules_digest()]    )def build_zeroshot_extra(family: str, task: str) -> str:    task = task.strip().lower()    fam = (family or "MOSFET").upper()    parts = [build_grammar_digest(fam)]    if task in ("nextstep", "completion"):        vocab = build_step_vocab_digest(fam)        if vocab:            parts.extend([vocab, _PREDICTION_MISTAKES])    if task == "anomaly":        parts.extend([_ANOMALY_GUIDANCE, build_anomaly_rules_digest()])    return "\n\n".join(p for p in parts if p)def build_messages(task: str, item: ValidInput | AnomalyInput) -> list[dict[str, str]]:    """Unified prompts; appends rules digest only when ``ZO_RULES_IN_CONTEXT=1``."""    family = getattr(item, "family", "MOSFET")    extra = build_zeroshot_extra(family, task) if use_rules_in_context() else None    return _build_unified_messages(task, item, system_extra=extra)__all__ = [    "build_anomaly_rules_digest",    "build_grammar_digest",    "build_messages",    "build_rules_digest",    "build_step_vocab_digest",    "build_zeroshot_extra",    "generation_rules_path",    "load_generation_rules",    "load_system_general",    "use_rules_in_context",]